                        $editLocation = $block->taskEvent?->latitude !== null ? ['latitude' => $block->taskEvent->latitude, 'longitude' => $block->taskEvent->longitude, 'city' => $block->taskEvent->city, 'suburb' => $block->taskEvent->suburb] : null;
